/* Browser demonstration. All confidentiality and permissions require a server. */
(function () {
  const pages = ['Scope package', 'Contractor pricing', 'Claims & invoices', 'Task progress', 'Business & team', 'Record of Work'];
  const clamp = n => Math.max(0, Math.min(100, Number.isFinite(n) ? n : 0));
  const id = () => 'co-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
  function setup(c) {
    ['contractorQuotes','claims','tasks','businessProfiles','rowDrafts','documents','inventory','tenderScopes','variations'].forEach(k => { if (!Array.isArray(c.store[k])) c.store[k] = []; });
    return c.projects.find(p => p.id === c.projectId) || c.project || c.projects[2] || c.projects[0];
  }
  const field = (e, name, title, value = '', type = 'text', extra = '') => `<label>${title}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
  function render(page, c) {
    const p = setup(c), e = c.escape, s = c.store, pid = p.id, mine = k => s[k].filter(x => x.projectId === pid);
    const f = (...a) => field(e, ...a);
    let html = `<div class="heading"><div><div class="eyebrow">CONTRACTOR WORKSPACE</div><h1>${e(page)}</h1><p>${e(p.name)} · ${e(pid)}</p></div></div><div class="co-context"><label>Project<select id="co-project">${c.projects.filter(x => x.id === pid || /contractor|build/i.test(x.stage)).map(x => `<option value="${e(x.id)}" ${x.id===pid?'selected':''}>${e(x.name)}</option>`).join('')}</select></label><span class="small">Fictional data · saved in this browser · no authenticated account</span></div>`;
    const scopes = mine('tenderScopes'), docs = mine('documents').filter(d => !d.visibility || d.visibility.includes('contractor'));
    if (page === 'Scope package') html += `<section class="card"><span class="tag amber">Awarded scope review</span><h2>One concise build package</h2><p>Customer: ${e(p.client)} · ${e(p.place)} · ${e(p.model)}</p><div class="co-columns"><div><h3>Included contractor work</h3>${scopes.length ? scopes.map(x=>`<p>${e(x.title || x.name || x.scope || 'Tender scope')} — ${e(x.description || x.requirements || '')}</p>`).join('') : '<ul><li>Site establishment and foundation coordination</li><li>Kit erection, structural fixings and weather-tight shell</li><li>Trade coordination and inspection readiness</li><li>Completion checks and construction records</li></ul><p class="small">Illustrative package; replace with the actual awarded tender.</p>'}</div><div><h3>Confirm before starting</h3><ul><li>Signed scope, exclusions and variations</li><li>Approved plans and consent conditions</li><li>Site access, services and delivery readiness</li><li>Inspections, responsibilities and programme</li></ul><p>Kit supply is Shed House’s responsibility only as agreed in the supply contract. Unpriced ground conditions and fit-out require explicit scope confirmation.</p></div></div></section><section class="card"><h2>Project documents</h2>${docs.map(d=>`<p><strong>${e(d.name)}</strong> · ${e(d.status)} · v${e(d.version || 1)} ${/^https:\/\//.test(d.url || '')?`<a href="${e(d.url)}" target="_blank" rel="noopener">Open document</a>`:''}</p>`).join('') || '<p>No shared documents yet. Shed House uploads will appear here.</p>'}</section><section class="card"><h2>Kitset inventory by category</h2>${[...new Set(mine('inventory').map(x=>x.category || 'Uncategorised'))].map(cat=>`<h3>${e(cat)}</h3>${mine('inventory').filter(x=>(x.category || 'Uncategorised')===cat).map(x=>`<p>${e(x.name || x.item || x.description)} · ${e(x.quantity || x.qty || 0)} ${e(x.unit || '')}</p>`).join('')}`).join('') || '<p>No inventory released for this project yet.</p>'}</section>`;
    if (page === 'Contractor pricing') html += `<section class="card co-notice"><h2>Your estimate workspace</h2><p>Quote cost lines are hidden from other role screens in this concept, but browser storage is not secure. Production needs server-enforced project access and separate contractor cost data. An NDA does not provide technical privacy.</p></section><form class="card co-form" id="co-quote"><h2>Add a cost line</h2>${f('description','Description','','text','required maxlength="150"')}${f('qty','Quantity',1,'number','min="0.01" step="0.01" required')}${f('rate','Rate excluding GST (NZD)',0,'number','min="0" step="0.01" required')}<label>Information sharing proposal<select name="sharing"><option value="private">Private internal cost line</option><option value="summary">Share tender total only after review</option><option value="nda">Request NDA review before tender summary</option></select></label><p class="small">No NDA is signed and nothing is sent by this demo.</p><button class="primary">Save cost line</button></form><section class="card"><h2>Estimate cost lines</h2>${mine('contractorQuotes').map(q=>`<div class="co-row"><div><strong>${e(q.description)}</strong><p>${e(q.qty)} × ${c.money(q.rate)} · ${e(q.sharing)}</p></div><strong>${c.money(q.qty*q.rate)}</strong><button class="secondary" data-co-remove="contractorQuotes:${e(q.id)}">Remove</button></div>`).join('') || '<p>No lines added.</p>'}<h3>Total excluding GST: ${c.money(mine('contractorQuotes').reduce((n,q)=>n+q.qty*q.rate,0))}</h3></section>`;
    if (page === 'Claims & invoices') html += `<section class="card"><h2>Draft a stage valuation</h2><p>Prepare a draft only. It is not issued or served as a statutory payment claim. Confirm the contract, valuation and service requirements before use.</p><p><a href="https://www.legislation.govt.nz/act/public/2002/0046/latest/whole.html" target="_blank" rel="noopener">Construction Contracts Act, section 20</a> · <a href="https://www.building.govt.nz/projects-and-consents/why-contracts-are-important/payment-disputes" target="_blank" rel="noopener">MBIE payment dispute guidance</a></p></section><form class="card co-form" id="co-claim">${f('reference','Contract / work reference','','text','required maxlength="150"')}${f('work','Work and valuation basis','','text','required maxlength="500"')}${f('from','Claim period start','','date','required')}${f('to','Claim period end','','date','required')}${f('valuation','Cumulative work value excluding GST',0,'number','required min="0" step="0.01"')}${f('previous','Previously claimed excluding GST',0,'number','required min="0" step="0.01"')}${f('gst','GST rate (%)',15,'number','required min="0" max="100" step="0.01"')}${f('due','Proposed due date','','date','required')}<button class="primary">Save draft valuation</button></form><section class="card"><h2>Drafts & validation</h2>${mine('claims').map(q=>`<div class="co-row"><div><strong>${e(q.reference)}</strong><p>${e(q.from)} – ${e(q.to)} · due ${e(q.due)}<br>${e(q.work)}<br>Net ${c.money(q.valuation-q.previous)} + GST ${c.money((q.valuation-q.previous)*q.gst/100)}</p><span class="tag amber">Draft · not served</span></div><strong>${c.money((q.valuation-q.previous)*(1+q.gst/100))}</strong></div>`).join('') || '<p>No draft claims.</p>'}<h3>Before any statutory claim is issued</h3><ul><li>Identify the construction contract and work / relevant period.</li><li>Show claimed amount, calculation basis and payment due date.</li><li>State it is made under the Construction Contracts Act 2002.</li><li>Accompany it with the current prescribed Form 1 notice and complete appropriate service.</li></ul><p>This checklist does not certify compliance; have the actual claim and current prescribed notice reviewed.</p></section>`;
    if (page === 'Task progress') html += `<form class="card co-form" id="co-task"><h2>Add a scope task</h2>${f('name','Scope task','','text','required maxlength="150"')}${f('plannedHours','Planned hours',40,'number','min="0" required step="0.5"')}${f('actualHours','Hours worked',0,'number','min="0" required step="0.5"')}${f('start','Planned start','','date','required')}${f('end','Planned completion','','date','required')}<label>Default progress measure<select name="mode"><option value="hours">Hours</option><option value="date">Date</option></select></label><button class="primary">Add task</button></form><section class="card"><h2>Scope task progress</h2><p>Hours show effort used; dates show elapsed programme. Neither alone proves work is complete.</p>${mine('tasks').map(t=>{const span=Date.parse(t.end)-Date.parse(t.start), hp=t.plannedHours>0?clamp(t.actualHours/t.plannedHours*100):0, dp=span>0?clamp((Date.now()-Date.parse(t.start))/span*100):0; return `<form class="co-task co-form" data-co-task="${e(t.id)}"><h3>${e(t.name)}</h3><label>Default meter<select name="mode"><option value="hours" ${t.mode==='hours'?'selected':''}>Hours</option><option value="date" ${t.mode==='date'?'selected':''}>Date</option></select></label><div class="co-meters ${t.mode==='date'?'co-date-first':''}"><div>Hours used: ${t.plannedHours>0?Math.round(hp)+'%':'Unplanned'} · ${e(t.actualHours)} / ${e(t.plannedHours)} h<div class="bar"><i style="width:${hp}%"></i></div></div><div>Programme elapsed: ${span>0?Math.round(dp)+'%':'Same-day task'}<div class="bar"><i style="width:${dp}%"></i></div><p>${e(t.start)} → ${e(t.end)}</p></div></div>${f('actualHours','Update hours worked',t.actualHours,'number','min="0" required step="0.5"')}<label><input name="complete" type="checkbox" ${t.complete?'checked':''}> Work completed and checked</label><button class="secondary">Update task</button></form>`;}).join('') || '<p>No tasks yet.</p>'}</section>`;
    if (page === 'Business & team') html += `<form class="card co-form" id="co-person"><h2>Business or subcontractor practitioner</h2>${f('business','Business name','','text','required maxlength="120"')}${f('person','Practitioner name','','text','required maxlength="120"')}${f('scope','Assigned work / trade','','text','required maxlength="200"')}${f('insurance','Insurance policy / holding','','text','maxlength="150"')}${f('insuranceExpiry','Insurance expiry','','date')}${f('lbp','LBP number / licence','','text','maxlength="80"')}${f('licenceClass','Licence class','','text','maxlength="120"')}${f('certificate','Certificate reference','','text','maxlength="200"')}${f('certificateExpiry','Certificate expiry','','date')}<button class="primary">Add team record</button></form><section class="card"><h2>Business & project team</h2><p>Self-declared demo records; verify insurance, licence register and certificates before appointment.</p>${mine('businessProfiles').map(b=>`<article class="co-task"><h3>${e(b.business)} · ${e(b.person)}</h3><p>${e(b.scope)}<br>LBP ${e(b.lbp || 'Not supplied')} · ${e(b.licenceClass || 'Class not supplied')}<br>Insurance: ${e(b.insurance || 'Not supplied')} · expires ${e(b.insuranceExpiry || 'Not supplied')} ${b.insuranceExpiry&&Date.parse(b.insuranceExpiry)<Date.now()?'<span class="tag amber">Check expiry</span>':''}<br>Certificate: ${e(b.certificate || 'Not supplied')} · expires ${e(b.certificateExpiry || 'Not supplied')}</p><a href="https://www.lbp.govt.nz/for-homeowners/find-an-lbp/" target="_blank" rel="noopener">Verify LBP details</a></article>`).join('') || '<p>No team records yet.</p>'}</section>`;
    if (page === 'Record of Work') html += `<section class="card co-notice"><h2>Completion records & payment are separate</h2><p>An LBP must not withhold a Record of Work because payment is outstanding. Track payment separately and provide the required record when the restricted building work is completed.</p><p><a href="https://www.lbp.govt.nz/for-lbps/skills-maintenance/codewords/records-of-work/" target="_blank" rel="noopener">Official LBP Record of Work guidance</a> · <a href="https://www.lbp.govt.nz/for-lbps/record-of-work/" target="_blank" rel="noopener">Official forms and instructions</a></p></section><form class="card co-form" id="co-row"><h2>Prepare completion record draft</h2><p>Project and awarded scope populate automatically. Select the practitioner responsible for the work; no signature is generated.</p><label>Practitioner<select name="practitioner" required><option value="">Select a project practitioner</option>${mine('businessProfiles').map(b=>`<option value="${e(b.id)}">${e(b.person)} · ${e(b.scope)}</option>`).join('')}</select></label>${f('work','Work carried out',scopes.map(x=>x.title || x.name || x.scope || '').filter(Boolean).join('; '),'text','required maxlength="1000"')}${f('completedOn','Work completion date','','date','required')}<label>Payment tracker<select name="payment"><option>Outstanding</option><option>Part paid</option><option>Paid in full</option></select></label><label><input type="checkbox" name="reviewed" required> I reviewed the work description and practitioner details</label><label><input type="checkbox" name="confirmed" required> The practitioner confirms this work is completed</label><button class="primary">Save reviewed draft</button></form><section class="card"><h2>Completion record drafts</h2>${mine('rowDrafts').map(r=>`<article class="co-task"><h3>${e(r.practitioner.person)} · ${e(r.completedOn)}</h3><p>${e(r.work)}<br>LBP ${e(r.practitioner.lbp || 'Missing — complete before official form')}<br>Payment: ${e(r.payment)} · ${r.released?'Shared with customer':'Awaiting release'}</p><p class="small">Draft preparation record, not the official prescribed ROW form.</p><button class="secondary" data-co-download="${e(r.id)}">Download draft text</button> <button class="primary" data-co-release="${e(r.id)}" ${r.released?'disabled':''}>Release reviewed completion draft</button></article>`).join('') || '<p>No completion drafts yet.</p>'}</section>`;
    return `<div class="co-workspace">${html}</div>`;
  }
  function bind(page,c) {
    const p=setup(c), s=c.store, root=document.querySelector('.co-workspace'); if(!root)return;
    const save=message=>{c.save();c.toast(message);c.navigate(page);};
    const form=(selector,handler)=>{const el=root.querySelector(selector);if(el)el.onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(el));handler(d);};};
    const add=(key,d)=>s[key].push({...d,id:id(),projectId:p.id});
    root.querySelector('#co-project').onchange=ev=>{c.store.contractorProjectId=ev.target.value;c.save();c.navigate(page);};
    form('#co-quote',d=>{d.qty=Number(d.qty);d.rate=Number(d.rate);if(!Number.isFinite(d.qty*d.rate)||d.qty<=0||d.rate<0)return c.toast('Enter valid positive quantities and non-negative rates.');add('contractorQuotes',d);save('Private demo cost line saved');});
    form('#co-claim',d=>{['valuation','previous','gst'].forEach(k=>d[k]=Number(d[k]));if(d.to<d.from||d.due<d.to||d.previous>d.valuation||!Number.isFinite(d.valuation+d.previous+d.gst))return c.toast('Check claim dates and valuation. Prior claims cannot exceed cumulative value.');add('claims',{...d,status:'Draft — not served'});save('Draft valuation saved; nothing issued');});
    form('#co-task',d=>{d.plannedHours=Number(d.plannedHours);d.actualHours=Number(d.actualHours);if(d.end<d.start||!Number.isFinite(d.actualHours+d.plannedHours))return c.toast('Check task dates and hours.');add('tasks',{...d,complete:false});save('Scope task added');});
    root.querySelectorAll('[data-co-task]').forEach(el=>el.onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(el)),t=s.tasks.find(x=>x.id===el.dataset.coTask);t.actualHours=Number(d.actualHours);t.mode=d.mode;t.complete=d.complete==='on';if(!Number.isFinite(t.actualHours)||t.actualHours<0)return c.toast('Check hours.');save('Task progress updated');});
    form('#co-person',d=>{add('businessProfiles',d);save('Team record saved for verification');});
    form('#co-row',d=>{const practitioner=s.businessProfiles.find(x=>x.id===d.practitioner&&x.projectId===p.id);if(!practitioner||!d.reviewed||!d.confirmed||d.completedOn>new Date().toISOString().slice(0,10))return c.toast('Choose a practitioner and confirm completed work with a valid completion date.');add('rowDrafts',{...d,practitioner:{...practitioner},reviewed:true,confirmed:true,released:false});save('Reviewed completion draft saved');});
    root.querySelectorAll('[data-co-remove]').forEach(b=>b.onclick=()=>{const [key,rid]=b.dataset.coRemove.split(':');s[key]=s[key].filter(x=>x.id!==rid||x.projectId!==p.id);save('Cost line removed');});
    root.querySelectorAll('[data-co-release]').forEach(b=>b.onclick=()=>{const r=s.rowDrafts.find(x=>x.id===b.dataset.coRelease&&x.projectId===p.id);if(!r||!r.reviewed||!r.confirmed)return c.toast('Review and practitioner confirmation are required.');r.released=true;add('documents',{name:`Completion draft — ${r.practitioner.person}`,type:'Completion record draft',status:'Shared draft — official ROW still required',version:1,url:'',visibility:['staff','customer','contractor'],uploadedAt:new Date().toISOString(),content:`${p.name}\n${r.work}\nPractitioner: ${r.practitioner.person}\nCompleted: ${r.completedOn}`});c.notify({title:'Completion record draft available',message:`${p.name}: reviewed completion draft shared. Official prescribed ROW must be provided separately.`,roles:['staff','customer'],projectId:p.id,kind:'document'});save('Completion draft shared independently of payment');});
    root.querySelectorAll('[data-co-download]').forEach(b=>b.onclick=()=>{const r=s.rowDrafts.find(x=>x.id===b.dataset.coDownload&&x.projectId===p.id);if(!r)return;const text=`DRAFT PREPARATION RECORD — NOT OFFICIAL ROW\n${p.id} — ${p.name}\nCustomer: ${p.client}\nWork: ${r.work}\nPractitioner: ${r.practitioner.person}\nLBP: ${r.practitioner.lbp || 'Not supplied'}\nLicence class: ${r.practitioner.licenceClass || 'Not supplied'}\nCompletion: ${r.completedOn}\nNo signature. Complete the official prescribed form separately.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=`${p.id}-completion-draft.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  }
  window.SHContractor={pages,render,bind};
})();
